practiceBank.starter:
#include <stdio.h>
int main(void) {
    int a, b; if (scanf("%d %d", &a, &b) != 2) return 1;
    // Напиши решение
    return 0;
}

practiceBank.solution:
#include <stdio.h>
int main(void) {
    int a, b; if (scanf("%d %d", &a, &b) != 2) return 1;
    while (b != 0) { int r = a % b; a = b; b = r; } int answer = a; printf("%d\n", answer);
    return 0;
}

