practiceBank.solution:
#include <stdio.h>
int main(void) {
    int n; if (scanf("%d", &n) != 1) return 1;
    int answer = 0; for (int i = 1; i <= n; i++) if (i % 3 == 0) answer += i; printf("%d\n", answer);
    return 0;
}

