#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>



int main(void) {
    char name[80];
    if (!fgets(name, sizeof name, stdin)) return 1;
    name[strcspn(name, "\r\n")] = 0;
    int age;
    if (scanf("%d", &age) != 1) return 1;
    printf("%s %d\n", name, age);
    return 0;
}

