#include <stdio.h>
#include <stdlib.h>

static int min(int a, int b) { return a < b ? a : b; }
static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) { return 1; }
    int a[20000];
    int count = 0;
    while (count < 20000 && scanf("%d", &a[count]) == 1) { count++; }
    int ending = a[0];
    int best = a[0];
    for (int i = 1; i < n; i++) {
        ending = max(a[i], ending + a[i]);
        best = max(best, ending);
    }
    printf("%d\n", best);
    return 0;
}

