#include <stdio.h>
#include <stdlib.h>

static int min(int a, int b) { return a < b ? a : b; }
static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) { return 1; }
    int a[20000];
    int count = 0;
    while (count < 20000 && scanf("%d", &a[count]) == 1) { count++; }
    int low = 0;
    int high = 0;
    for (int i = 0; i < n; i++) {
        low = max(low, a[i]);
        high += a[i];
    }
    while (low < high) {
        int middle = low + (high - low) / 2;
        int groups = 1;
        int load = 0;
        for (int i = 0; i < n; i++) {
            if (load + a[i] > middle) {
                groups++;
                load = 0;
            }
            load += a[i];
        }
        if (groups <= k) {
            high = middle;
        } else {
            low = middle + 1;
        }
    }
    printf("%d\n", low);
    return 0;
}

