#include <stdio.h>
#include <stdlib.h>

static int min(int a, int b) { return a < b ? a : b; }
static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) { return 1; }
    int a[20000];
    int count = 0;
    while (count < 20000 && scanf("%d", &a[count]) == 1) { count++; }
    int *dp = malloc(((k + 1) > 0 ? (k + 1) : 1) * sizeof *dp);
    if (dp == NULL) { return 1; }
    for (int fill = 0; fill < k + 1; fill++) { dp[fill] = 1000000; }
    dp[0] = 0;
    for (int amount = 1; amount <= k; amount++) {
        for (int i = 0; i < n; i++) {
            if (a[i] <= amount) {
                dp[amount] = min(dp[amount], dp[amount - a[i]] + 1);
            }
        }
    }
    int answer = dp[k];
    if (answer >= 1000000) {
        answer = -1;
    }
    printf("%d\n", answer);
    free(dp);
    return 0;
}

