sections.code:
#include <stdio.h>
#include <stdlib.h>

static int min(int a, int b) { return a < b ? a : b; }
static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) { return 1; }
    int a[20000];
    int count = 0;
    while (count < 20000 && scanf("%d", &a[count]) == 1) { count++; }
    int *dp = malloc(((n) > 0 ? (n) : 1) * sizeof *dp);
    if (dp == NULL) { return 1; }
    for (int fill = 0; fill < n; fill++) { dp[fill] = 1; }
    int answer = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (a[j] < a[i]) {
                dp[i] = max(dp[i], dp[j] + 1);
            }
        }
        answer = max(answer, dp[i]);
    }
    printf("%d\n", answer);
    free(dp);
    return 0;
}

