#include <stdio.h>
#include <stdlib.h>

static int min(int a, int b) { return a < b ? a : b; }
static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) { return 1; }
    int a[20000];
    int count = 0;
    while (count < 20000 && scanf("%d", &a[count]) == 1) { count++; }
    int *distance = malloc(((n) > 0 ? (n) : 1) * sizeof *distance);
    if (distance == NULL) { return 1; }
    for (int fill = 0; fill < n; fill++) { distance[fill] = 1000000000; }
    int *used = malloc(((n) > 0 ? (n) : 1) * sizeof *used);
    if (used == NULL) { return 1; }
    for (int fill = 0; fill < n; fill++) { used[fill] = 0; }
    distance[k] = 0;
    for (int step = 0; step < n; step++) {
        int vertex = -1;
        for (int i = 0; i < n; i++) {
            if (used[i] == 0) {
                if (vertex == -1 || distance[i] < distance[vertex]) {
                    vertex = i;
                }
            }
        }
        if (vertex == -1 || distance[vertex] == 1000000000) {
            break;
        }
        used[vertex] = 1;
        for (int next = 0; next < n; next++) {
            int weight = a[vertex * n + next];
            if (weight >= 0 && used[next] == 0) {
                distance[next] = min(distance[next], distance[vertex] + weight);
            }
        }
    }
    for (int i = 0; i < n; i++) {
        int value = distance[i];
        if (value == 1000000000) {
            value = -1;
        }
        printf("%d\n", value);
    }
    free(distance);
    free(used);
    return 0;
}

